// Process error from failed workflow
const error = $input.first().json;

const errorReport = {
  type: 'workflow_error',
  severity: 'error',
  timestamp: new Date().toISOString(),

  // Error details
  error: {
    message: error.message || 'Unknown error',
    workflow: error.workflow?.name || 'Unknown',
    workflowId: error.workflow?.id,
    node: error.node?.name || 'Unknown',
    nodeType: error.node?.type,
    executionId: error.execution?.id
  },

  // Context
  context: {
    mode: error.execution?.mode,
    retryOfExecutionId: error.execution?.retryOf,
    startedAt: error.execution?.startedAt
  },

  // Action required
  actionRequired: true,
  suggestedAction: (() => {
    const msg = (error.message || '').toLowerCase();
    if (msg.includes('timeout')) return 'Check service availability';
    if (msg.includes('authentication')) return 'Verify API credentials';
    if (msg.includes('rate limit')) return 'Implement retry with backoff';
    if (msg.includes('404')) return 'Check endpoint URL';
    return 'Review error logs';
  })()
};

return errorReport;

// Analyze health check results
const apiResponse = $input.first().json;
const isError = $input.first().error;

const healthReport = {
  timestamp: new Date().toISOString(),
  checkType: 'scheduled',

  services: {
    api: {
      status: isError ? 'down' : 'healthy',
      responseTime: apiResponse?._meta?.responseTime || null,
      uptime: apiResponse?.uptime || null,
      error: isError ? 'API unreachable' : null
    },
    n8n: {
      status: 'healthy', // If we're running, n8n is up
      executionId: $execution.id
    }
  },

  // Overall status
  overallStatus: isError ? 'degraded' : 'healthy',

  // Metrics
  metrics: {
    apiHealthy: !isError,
    lastCheck: new Date().toISOString()
  }
};

return healthReport;

// Generate alert for unhealthy status
const health = $input.first().json;

const alert = {
  type: 'health_alert',
  severity: health.overallStatus === 'down' ? 'critical' : 'warning',
  title: `System Health Alert: ${health.overallStatus.toUpperCase()}`,

  message: (() => {
    const issues = [];
    if (health.services.api.status !== 'healthy') {
      issues.push(`API service is ${health.services.api.status}`);
    }
    return issues.join('; ') || 'Unknown issue detected';
  })(),

  services: health.services,
  timestamp: new Date().toISOString(),

  // Notification targets
  notify: {
    slack: true,
    email: health.overallStatus === 'down',
    pagerDuty: health.overallStatus === 'down'
  }
};

return alert;

// Generate error alert
const error = $input.first().json;

const alert = {
  type: 'error_alert',
  severity: 'error',
  title: `Workflow Error: ${error.error.workflow}`,

  message: error.error.message,

  details: {
    workflow: error.error.workflow,
    node: error.error.node,
    nodeType: error.error.nodeType,
    executionId: error.error.executionId,
    suggestedAction: error.suggestedAction
  },

  timestamp: error.timestamp,

  // Link to execution
  executionUrl: `${process.env.N8N_HOST || 'http://localhost:5678'}/workflow/${error.error.workflowId}/executions/${error.error.executionId}`,

  notify: {
    slack: true,
    email: true
  }
};

return alert;

// Log alert (would send to Slack/Email in production)
const alert = $input.first().json;

console.log('=== ALERT ===');
console.log(`Type: ${alert.type}`);
console.log(`Severity: ${alert.severity}`);
console.log(`Title: ${alert.title}`);
console.log(`Message: ${alert.message}`);
console.log('=============');

return {
  alertLogged: true,
  alert,
  loggedAt: new Date().toISOString()
};

// Generate daily health digest
const digest = {
  type: 'daily_digest',
  date: new Date().toISOString().split('T')[0],
  generatedAt: new Date().toISOString(),

  summary: {
    title: 'AutoScale CRM - Daily Health Digest',
    period: '24 hours',
    overallHealth: 'healthy', // Would be calculated from actual metrics
  },

  metrics: {
    workflowExecutions: {
      total: 156, // Placeholder - would query actual data
      successful: 152,
      failed: 4,
      successRate: '97.4%'
    },
    leadsProcessed: {
      total: 23,
      qualified: 8,
      nurture: 12,
      disqualified: 3
    },
    apiPerformance: {
      averageResponseTime: '45ms',
      uptime: '99.9%',
      totalRequests: 1250
    }
  },

  alerts: {
    critical: 0,
    warning: 2,
    info: 5
  },

  recommendations: [
    'Review 4 failed workflow executions',
    'Consider re-engaging 12 nurture leads',
    'API response times within normal range'
  ]
};

return digest;
